"""Summarize the supplied CCMC registry snapshot without implying product approval."""
import pathlib,json,hashlib,collections
ROOT=pathlib.Path(__file__).resolve().parents[2];OUT=ROOT/'research/precedents';f=ROOT/'reference/data/ccmc-registry.json';data=json.loads(f.read_text());rows=data['items']
mfs=collections.Counter();division=collections.Counter();references=collections.Counter();examples=collections.defaultdict(list);malformed=[]
for r in rows:
 try:codes=json.loads(r['mfs']) if r.get('mfs') else [];refs=json.loads(r['refdoc_eng']) if r.get('refdoc_eng') else []
 except (ValueError,TypeError) as e:malformed.append({'ccmcno':r['ccmcno'],'error':str(e)});continue
 mfs.update(set(codes));division.update({v.split()[0] for v in codes});references.update(set(refs))
 for v in set(codes):
  if len(examples[v])<3:examples[v].append({'ccmcno':r['ccmcno'],'products':json.loads(r['products_eng'])})
summary={'source_local_path':str(f.relative_to(ROOT)),'source_url':next(x['href'] for x in data['links'] if x['rel']=='self'),'accessed':'2026-10-18','source_sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'population':'The provided registry snapshot, not a new download of all individual assessment reports.','assessments':len(rows),'has_more':data['hasMore'],'status_counts':dict(collections.Counter(r['status_eng'] for r in rows)),'unique_ids':len({r['id'] for r in rows}),'unique_ccmc_numbers':len({r['ccmcno'] for r in rows}),'missing_masterformat':sum(not r.get('mfs') or r.get('mfs')=='[]' for r in rows),'missing_reference_documents':sum(not r.get('refdoc_eng') or r.get('refdoc_eng')=='[]' for r in rows),'malformed_json_fields':malformed,'masterformat_divisions':[{'code':k,'assessments':v} for k,v in division.most_common()],'masterformat_categories':[{'code':k,'assessments':v,'examples':examples[k]} for k,v in mfs.most_common()],'reference_documents':[{'reference':k,'assessments':v} for k,v in references.most_common()],'counting_rule':'Each assessment counted once per distinct category/division/reference string. Categories overlap; totals across categories are not additive. Reference strings preserve edition/type/amendment text.','product_path':['Match product/manufacturer and exact CCMC number; retrieve the actual published assessment.','Check current status, assessment type, evaluated code editions, product specification and intended installation.','Compare project use with report limitations, permitted substrates/assemblies, load/climate/fire conditions, installation and quality-control requirements.','Extract the specific test standards/evidence and use them to request supporting documents; the registry row alone does not establish performance or acceptance.','Verify Alberta adoption/current article mappings separately; identify whether an acceptable-solution route exists or a project alternative solution is still required.','Carry the report and responsible professional into Section D evidence; leave performance judgment to the AHJ/professional.']}
(OUT/'ccmc-summary.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False)+'\n')
print('CCMC',len(rows),'assessments;',summary['missing_masterformat'],'missing classifications;',len(malformed),'malformed fields')
